def drive(me, enemy, arena):
    # If we cannot drive, stay still
    if not me.can_drive:
        return (0, 0)

    # Aim roughly toward the enemy
    bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive = left
    turn = 0.0
    if bearing > 5:
        turn = -0.3   # turn right a bit
    elif bearing < -5:
        turn = 0.3    # turn left a bit

    # Throttle based on distance: faster when far
    dist = distance_to(enemy.x, enemy.y)
    throttle = 0.8 if dist > 1.0 else 0.4

    left = throttle + turn
    right = throttle - turn

    # Clamp to allowed range
    left = max(-1, min(1, left))
    right = max(-1, min(1, right))
    return (left, right)


def weapons(me, enemy, arena):
    cmds = []
    # Spin up when within striking range, otherwise stop
    if distance_to(enemy.x, enemy.y) < 2.0:
        cmds.append(spin("front", 5000))
    else:
        cmds.append(spin("front", 0))
    return cmds

def drive(me, enemy, arena):
    # Compute bearing to enemy using the provided function
    bearing = bearing_to(enemy.x, enemy.y)          # degrees, -180..180
    # Normalise just in case
    if bearing > 180:
        bearing -= 360
    elif bearing < -180:
        bearing += 360

    # Proportional turning, limited to full throttle
    turn = max(-1.0, min(1.0, bearing / 45.0))      # 45° -> full differential
    left  = 1.0 - turn
    right = 1.0 + turn
    # Clamp to allowed range
    left  = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


